let BD_CENTER_GROUPS = (window.__BD_CENTER_GROUPS || []);

// Expose globally for the panel bridge
window.BD_CENTER_GROUPS = BD_CENTER_GROUPS;
window.__bdSetGroups = function(g){ BD_CENTER_GROUPS = g || []; window.BD_CENTER_GROUPS = BD_CENTER_GROUPS; };
window.addEventListener("message", function(e){ if(e.source===window && e.data && e.data.__bd && e.data.type==="setGroups"){ window.__bdSetGroups(e.data.groups); } });

/* ===================== PATCH: strict targeted medical center ===================== */
// Remembers the user's chosen center so it survives Wafid's reset handlers and is
// FORCED into the real submit field right before the form POSTs.
window.__BD_SELECTED_MC = window.__BD_SELECTED_MC || { value: "", name: "" };

function bdSetSelectedMC(value, name) {
  window.__BD_SELECTED_MC = { value: String(value || ""), name: name || "" };
  bdForceMCValue();
}
window.bdSetSelectedMC = bdSetSelectedMC;

// Writes the remembered value into #id_medical_center, creating the <option> if missing.
function bdForceMCValue() {
  const sel = document.getElementById("id_medical_center");
  const chosen = window.__BD_SELECTED_MC;
  if (!sel || !chosen || !chosen.value) return false;
  let opt = Array.from(sel.options).find(o => o.value === String(chosen.value));
  if (!opt) {
    opt = document.createElement("option");
    opt.value = chosen.value;
    opt.textContent = chosen.name ? `${chosen.name} (${chosen.value})` : chosen.value;
    sel.appendChild(opt);
  }
  sel.value = String(chosen.value);
  // keep Semantic UI widget (if any) in sync, but DO NOT fire native change
  // (change re-triggers Wafid's reset); just refresh the visual widget.
  if (window.$ && window.$.fn && window.$.fn.dropdown) {
    try {
      window.$(sel).dropdown("refresh");
      window.$(sel).dropdown("set selected", String(chosen.value));
    } catch (e) {}
  }
  return true;
}
window.bdForceMCValue = bdForceMCValue;

// Install the submit guard once. Capture phase runs BEFORE Wafid's own submit
// handlers, guaranteeing the chosen center is present in the POST body.
function bdInstallSubmitGuard() {
  const form = document.querySelector("form");
  if (!form || form.__bdGuarded) return;
  form.__bdGuarded = true;
  form.addEventListener("submit", () => { bdForceMCValue(); }, true);

  // Also guard any explicit submit button clicks.
  document.querySelectorAll('form button[type="submit"], form input[type="submit"]').forEach(btn => {
    btn.addEventListener("click", () => { bdForceMCValue(); }, true);
  });

  // If Wafid scripts wipe the option list after our selection, re-apply it.
  const sel = document.getElementById("id_medical_center");
  if (sel && !sel.__bdObserved) {
    sel.__bdObserved = true;
    const mo = new MutationObserver(() => {
      const chosen = window.__BD_SELECTED_MC;
      if (chosen && chosen.value && sel.value !== String(chosen.value)) {
        bdForceMCValue();
      }
    });
    mo.observe(sel, { childList: true });
  }
}
window.bdInstallSubmitGuard = bdInstallSubmitGuard;
/* =================== END PATCH =================== */

function injectBDMedicalCenters() {
  const DESTS = ["BH", "KW", "OM", "QA", "SA", "UAE", "AE", "YEM"];

  // 1. Always push "BD" to MANUAL_MEDICAL_CENTER_COUNTRIES
  if (window.MANUAL_MEDICAL_CENTER_COUNTRIES && !window.MANUAL_MEDICAL_CENTER_COUNTRIES.includes("BD")) {
    window.MANUAL_MEDICAL_CENTER_COUNTRIES.push("BD");
  }

  // 2. Inject into Wafid's global CITY_MEDICAL_CENTERS so native scripts also recognize them
  if (window.CITY_MEDICAL_CENTERS) {
    BD_CENTER_GROUPS.forEach(group => {
      const entries = [];
      group.centers.forEach(c => {
        DESTS.forEach(dest => {
          entries.push([Number(c.value), c.name, Number(group.cityId), dest]);
        });
      });
      window.CITY_MEDICAL_CENTERS[group.cityId] = entries;
    });
  }
}

function unlockAndPopulateDropdown() {
  injectBDMedicalCenters();

  const countryEl = document.getElementById("id_country");
  const cityEl = document.getElementById("id_city");
  const mcSelect = document.getElementById("id_medical_center");
  const chooseMcDiv = document.getElementById("choose-mc");

  if (!countryEl || !mcSelect) return;

  const country = countryEl.value;
  const cityId = cityEl ? cityEl.value : "";

  if (country && window.MANUAL_MEDICAL_CENTER_COUNTRIES && !window.MANUAL_MEDICAL_CENTER_COUNTRIES.includes(country)) {
    window.MANUAL_MEDICAL_CENTER_COUNTRIES.push(country);
  }

  // Unhide #choose-mc and #id_medical_center
  if (chooseMcDiv) {
    chooseMcDiv.classList.remove("hidden");
    chooseMcDiv.style.display = "block";
    chooseMcDiv.style.height = "auto";
  }

  mcSelect.removeAttribute("disabled");
  mcSelect.style.display = "block";

  const parentField = mcSelect.closest(".field");
  if (parentField) {
    parentField.classList.remove("hidden", "disabled");
    parentField.style.display = "block";
  }

  const uiDropdown = mcSelect.closest(".ui.dropdown");
  if (uiDropdown) {
    uiDropdown.classList.remove("hidden", "disabled");
    uiDropdown.style.display = "block";
  }

  // Hide the "Medical center has been assigned automatically" notice
  document.querySelectorAll("#choose-mc .info, .medical-center-field-js .ui.message").forEach(el => {
    el.style.display = "none";
  });

  // Populate options if Bangladesh is selected
  if (country === "BD") {
    const currentSelected = mcSelect.value;
    mcSelect.innerHTML = '<option value="">Select Medical Center</option>';

    const matchedGroup = BD_CENTER_GROUPS.find(g => g.cityId === String(cityId));

    if (matchedGroup) {
      // Show only the selected city's centers
      matchedGroup.centers.forEach(c => {
        const opt = document.createElement("option");
        opt.value = c.value;
        opt.textContent = `${c.name} (${c.value})`;
        mcSelect.appendChild(opt);
      });
    } else {
      // If no city or another city is selected, show all BD centers grouped by City
      BD_CENTER_GROUPS.forEach(group => {
        const optgroup = document.createElement("optgroup");
        optgroup.label = group.label;
        group.centers.forEach(c => {
          const opt = document.createElement("option");
          opt.value = c.value;
          opt.textContent = `${c.name} (${c.value})`;
          optgroup.appendChild(opt);
        });
        mcSelect.appendChild(optgroup);
      });
    }

    const remembered = window.__BD_SELECTED_MC && window.__BD_SELECTED_MC.value;
    if (remembered) {
      bdForceMCValue();
    } else if (currentSelected) {
      mcSelect.value = currentSelected;
    }

    if (window.$&& window.$.fn.dropdown) {
      window.$(mcSelect).dropdown("refresh");
    }
  }
}

window.unlockAndPopulateDropdown = unlockAndPopulateDropdown;

// Run automatically on load and when user changes Country/City/Destination
window.addEventListener("load", () => {
  setTimeout(() => { unlockAndPopulateDropdown(); bdInstallSubmitGuard(); }, 800);

  // When the user picks a center directly in the page dropdown, remember it.
  const mcEl = document.getElementById("id_medical_center");
  if (mcEl) {
    mcEl.addEventListener("change", (e) => {
      if (!e.isTrusted) return;                      // ignore site's programmatic auto-select
      if (mcEl.value) {
        const t = mcEl.options[mcEl.selectedIndex]?.text || "";
        window.__BD_SELECTED_MC = { value: String(mcEl.value), name: t.replace(/\s*\(\d+\)$/, "") };
      }
    });
  }

  ["id_country", "id_city", "id_traveled_country"].forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.addEventListener("change", () => {
        setTimeout(unlockAndPopulateDropdown, 300);
      });
    }
  });
});
/* ===================== AUTO FORM FILL-UP ===================== */
// Field names are the exact ones Wafid POSTs (taken from fer.har).
(function () {
  const sleep = ms => new Promise(r => setTimeout(r, ms));

  function waitFor(fn, timeout = 4000, step = 100) {
    return new Promise(resolve => {
      const t0 = Date.now();
      (function tick() {
        let ok = false;
        try { ok = fn(); } catch (e) {}
        if (ok) return resolve(true);
        if (Date.now() - t0 > timeout) return resolve(false);
        setTimeout(tick, step);
      })();
    });
  }

  const byName = n => document.querySelector(`form [name="${n}"]`);

  // Selects: go through jQuery so Wafid's own change handlers run
  // (country -> city list, city -> medical centers, etc.).
  function setSelect(name, value) {
    const el = byName(name);
    if (!el || value === undefined || value === null || value === "") return false;
    const v = String(value);
    if (!Array.from(el.options).some(o => o.value === v)) return false;
    if (window.$) {
      window.$(el).val(v).trigger("change");
      try { if (window.$.fn.dropdown) window.$(el).dropdown("set selected", v); } catch (e) {}
    } else {
      el.value = v;
      el.dispatchEvent(new Event("change", { bubbles: true }));
    }
    return el.value === v;
  }

  // Text inputs: native setter + input/change/blur so validators & inputmask see it.
  function setText(name, value) {
    const el = byName(name);
    if (!el || value === undefined || value === null || value === "") return false;
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
    el.focus();
    setter.call(el, String(value));
    ["input", "change", "keyup", "blur"].forEach(ev => el.dispatchEvent(new Event(ev, { bubbles: true })));
    if (window.$) window.$(el).trigger("change");
    return true;
  }

  // Wafid date format is D/M/YYYY (calendar-widget.js formatter). Input: YYYY-MM-DD.
  function setDate(name, iso) {
    const el = byName(name);
    if (!el || !iso) return false;
    const [y, m, d] = iso.split("-").map(Number);
    if (!y || !m || !d) return false;
    const cal = window.$ ? window.$(el).closest(".calendar-js, .ui.calendar") : null;
    if (cal && cal.length && window.$.fn.calendar) {
      try { cal.calendar("set date", new Date(y, m - 1, d, 12, 0, 0, 0)); } catch (e) {}
    }
    if (el.value !== `${d}/${m}/${y}`) setText(name, `${d}/${m}/${y}`);
    return true;
  }

  async function bdAutoFill(p, mc) {
    mc = (mc && mc.value) ? mc : window.__BD_SELECTED_MC;
    const log = [];
    const ok = (k, r) => log.push({ k, ok: !!r });

    // 1) Location chain (each step rebuilds the next dropdown, so wait for it)
    ok("country", setSelect("country", p.country || "BD"));
    await waitFor(() => byName("city") && byName("city").options.length > 1);
    await sleep(200);
    ok("city", setSelect("city", p.city));
    await sleep(300);
    ok("traveled_country", setSelect("traveled_country", p.traveled_country));
    await sleep(300);

    // 2) Appointment type = standard
    const std = document.querySelector('input[name="appointment_type"][value="standard"]');
    if (std && !std.checked) { std.click(); std.dispatchEvent(new Event("change", { bubbles: true })); }
    ok("appointment_type", !!(std && std.checked));
    await sleep(300);

    // 3) Medical center (strict, uses the submit guard)
    if (mc && mc.value && typeof unlockAndPopulateDropdown === "function") unlockAndPopulateDropdown();
    if (typeof bdInstallSubmitGuard === "function") bdInstallSubmitGuard();
    if (mc && mc.value) {
      bdSetSelectedMC(mc.value, mc.name);
      ok(`medical_center #${mc.value}`, document.getElementById("id_medical_center")?.value === String(mc.value));
    } else {
      log.push({ k: "medical_center (not selected)", ok: false });
    }

    // 4) Candidate info
    ok("first_name", setText("first_name", p.first_name));
    ok("last_name", setText("last_name", p.last_name));
    ok("dob", setDate("dob", p.dob));
    ok("nationality", setSelect("nationality", p.nationality || "15"));
    await sleep(200); // nationality toggles national_id "optional" label
    ok("gender", setSelect("gender", p.gender));
    ok("marital_status", setSelect("marital_status", p.marital_status));
    ok("passport", setText("passport", p.passport));
    ok("confirm_passport", setText("confirm_passport", p.passport));
    ok("passport_issue_date", setDate("passport_issue_date", p.passport_issue_date));
    ok("passport_issue_place", setText("passport_issue_place", p.passport_issue_place));
    ok("passport_expiry_on", setDate("passport_expiry_on", p.passport_expiry_on));
    ok("visa_type", setSelect("visa_type", p.visa_type));
    ok("email", setText("email", p.email));
    ok("phone", setText("phone", p.phone));
    ok("national_id", setText("national_id", p.national_id));
    ok("applied_position", setSelect("applied_position", p.applied_position));
    if (String(p.applied_position) === "108") {
      await sleep(200);
      ok("applied_position_other", setText("applied_position_other", p.applied_position_other));
    }

    // 5) Confirm checkbox
    const cb = document.getElementById("id_confirm");
    if (cb && !cb.checked) {
      const wrap = window.$ ? window.$(cb).closest(".ui.checkbox") : null;
      if (wrap && wrap.length && window.$.fn.checkbox) { try { wrap.checkbox("check"); } catch (e) {} }
      if (!cb.checked) cb.click();
    }
    ok("confirm", !!(cb && cb.checked));

    // Final re-apply of the center (city/destination handlers may have reset it)
    if (mc && mc.value) bdForceMCValue();
    return log;
  }

  window.bdAutoFill = bdAutoFill;
})();
/* =================== END AUTO FILL =================== */

/* ===================== VERIFIER + PANEL BRIDGE (MAIN world) ===================== */
// The floating panel (panel.js) runs in the extension's isolated world and talks to
// this code via window.postMessage. Messages are tagged with __bd.
(function () {
  const KEY = "__bd_last_post";
  const isBooking = /\/book-appointment\/?/.test(location.pathname);
  const isPay = /\/appointment\/[^/]+\/pay\/?/.test(location.pathname);
  let bypass = false;

  const mainForm = () => document.getElementById("id_medical_center")?.closest("form") || null;

  function centerName(id) {
    for (const g of BD_CENTER_GROUPS) for (const c of g.centers) if (c.value === String(id)) return c.name;
    return "";
  }

  // Reads EXACTLY what the browser will POST.
  function verify() {
    const chosen = (window.__BD_SELECTED_MC && window.__BD_SELECTED_MC.value) || "";
    const f = mainForm();
    if (!f) return { status: "missing", sent: null, chosen, p: {} };
    const fd = new FormData(f);
    const p = {
      country: fd.get("country") || "", city: fd.get("city") || "",
      traveled_country: fd.get("traveled_country") || "", appointment_type: fd.get("appointment_type") || ""
    };
    const sent = fd.has("medical_center") ? String(fd.get("medical_center")) : null;
    let status = "ok";
    if (sent === null) status = "missing";
    else if (sent === "") status = "empty";
    else if (!chosen) status = "unchosen";          // site auto-picked a center, not you
    else if (sent !== chosen) status = "mismatch";
    return { status, sent, sentName: sent ? centerName(sent) : "", chosen, chosenName: chosen ? centerName(chosen) : "", p };
  }
  window.bdVerifyPayload = verify;

  const post = msg => window.postMessage(Object.assign({ __bd: true }, msg), location.origin);

  function saveLast(v, forced) {
    try {
      sessionStorage.setItem(KEY, JSON.stringify({
        medical_center: v.sent || "", name: v.sentName || "", chosen: v.chosen,
        city: v.p.city, traveled_country: v.p.traveled_country, forced: !!forced, at: new Date().toISOString()
      }));
    } catch (e) {}
  }

  // Submit gate: blocks synchronously; the panel shows a modal and can force-submit.
  function gate() {
    if (bypass || window.__bdBypassOnce) { bypass = false; window.__bdBypassOnce = false; return true; }
    if (typeof bdForceMCValue === "function") bdForceMCValue();
    const v = verify();
    if (v.status === "ok") { saveLast(v, false); return true; }
    post({ type: "gate", v });
    return false;
  }

  if (isBooking) {
    document.addEventListener("submit", e => {
      if (e.target !== mainForm()) return;
      if (!gate()) { e.preventDefault(); e.stopImmediatePropagation(); }
    }, true);
    const nativeSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function () {
      if (this === mainForm() && !gate()) return;
      return nativeSubmit.apply(this, arguments);
    };
    window.__bdNativeSubmit = nativeSubmit;
  }

  function state() {
    if (isPay) {
      let last = null;
      try { last = JSON.parse(sessionStorage.getItem(KEY) || "null"); } catch (e) {}
      return { page: "pay", last };
    }
    const cityEl = document.getElementById("id_city");
    return {
      page: "booking",
      v: verify(),
      cityName: cityEl && cityEl.selectedIndex > 0 ? cityEl.options[cityEl.selectedIndex].text : "",
      selected: window.__BD_SELECTED_MC || { value: "", name: "" }
    };
  }

  // Push live state to the panel.
  setInterval(() => post({ type: "state", state: state() }), 500);

  // Requests from panel.
  window.addEventListener("message", async e => {
    if (e.source !== window || !e.data || !e.data.__bd || e.data.type !== "req") return;
    const { id, cmd, args } = e.data;
    if (/^mon/.test(cmd)) return;
    let result = null;
    try {
      if (cmd === "groups") result = BD_CENTER_GROUPS;
      else if (cmd === "state") result = state();
      else if (cmd === "unlock") { unlockAndPopulateDropdown(); bdInstallSubmitGuard(); result = true; }
      else if (cmd === "select") {
        unlockAndPopulateDropdown(); bdInstallSubmitGuard();
        bdSetSelectedMC(args.value, args.name);
        result = document.getElementById("id_medical_center")?.value === String(args.value);
      }
      else if (cmd === "autofill") result = await bdAutoFill(args.profile, null);
      else if (cmd === "forceSubmit") {
        const f = mainForm();
        if (f) {
          saveLast(verify(), true);
          bypass = true;
          if (f.requestSubmit) f.requestSubmit(); else window.__bdNativeSubmit.call(f);
          setTimeout(() => { bypass = false; }, 1000);
          result = true;
        }
      }
    } catch (err) { result = { error: String(err) }; }
    post({ type: "res", id, result });
  });
})();
/* =================== END VERIFIER + BRIDGE =================== */


/* ===================== LIVE AUTO-ASSIGN MONITOR (MAIN world) ===================== */
// Wafid embeds COUNTRY_MEDICAL_CENTER in the booking page. For BD it holds the center the
// server will auto-assign next, per destination. We re-fetch the page, read it, and when the
// live center equals one of the user's targets, submit the (pre-filled) form with
// medical_center = "" so the server's auto-assign gives that center.
(function () {
  const isBooking = /\/book-appointment\/?/.test(location.pathname);
  const isPay = /\/appointment\/[^/]+\/pay\/?/.test(location.pathname);
  const CKEY = "__bd_mon_cfg", LKEY = "__bd_live_log", RKEY = "__bd_mon_result";
  const post = m => window.postMessage(Object.assign({ __bd: true }, m), location.origin);
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const form = () => document.getElementById("id_medical_center")?.closest("form") || document.querySelector("form[method=post]");

  let cfg = null, timer = null, busy = false;
  const info = { running: false, live: {}, checkedAt: 0, polls: 0, errors: 0, lastErr: "", fired: null, phase: "idle", note: "" };

  function parseCMC(html) {
    const m = html.match(/COUNTRY_MEDICAL_CENTER\s*=\s*JSON\.parse\("((?:[^"\\]|\\.)*)"\)/);
    if (!m) return null;
    let d; try { d = JSON.parse(JSON.parse('"' + m[1] + '"')); } catch (e) { return null; }
    return toLive(d);
  }
  function toLive(d) {
    const out = {};
    ((d && d.BD) || []).forEach(x => { out[x[3]] = { id: String(x[0]), name: String(x[1]) }; });
    return out;
  }
  function readLog() { try { return JSON.parse(localStorage.getItem(LKEY) || "[]"); } catch (e) { return []; } }
  function record(live) {
    const log = readLog(); const last = {};
    for (const e of log) last[e.dest] = e.id;
    let changed = false;
    for (const [dest, c] of Object.entries(live)) {
      if (last[dest] !== c.id) { log.push({ t: Date.now(), dest, id: c.id, name: c.name }); changed = true; }
    }
    if (changed) { while (log.length > 300) log.shift(); try { localStorage.setItem(LKEY, JSON.stringify(log)); } catch (e) {} }
  }
  function saveCfg() { try { sessionStorage.setItem(CKEY, JSON.stringify(cfg)); } catch (e) {} }
  function push() { post({ type: "mon", info: Object.assign({}, info, { cfg, log: readLog().slice(-25).reverse(), result: getResult() }) }); }
  function getResult() { try { return JSON.parse(sessionStorage.getItem(RKEY) || "null"); } catch (e) { return null; } }

  function beep() {
    try {
      const A = new (window.AudioContext || window.webkitAudioContext)();
      [0, 0.25, 0.5].forEach(t => { const o = A.createOscillator(), g = A.createGain(); o.frequency.value = 880; g.gain.value = 0.25;
        o.connect(g); g.connect(A.destination); o.start(A.currentTime + t); o.stop(A.currentTime + t + 0.18); });
    } catch (e) {}
    const t0 = document.title; let n = 0;
    const iv = setInterval(() => { document.title = (n++ % 2 ? "MATCH! " : "") + t0; if (n > 20) { clearInterval(iv); document.title = t0; } }, 500);
  }

  async function freshCaptcha() {
    const el = document.getElementById("id_captcha") || document.querySelector("input.g-recaptcha");
    if (!el || !window.grecaptcha || !grecaptcha.execute) return false;
    const key = el.getAttribute("data-sitekey");
    try {
      const tok = await Promise.race([
        new Promise(res => grecaptcha.ready(() => grecaptcha.execute(key, { action: "form" }).then(res, () => res(null)))),
        sleep(8000).then(() => null)
      ]);
      if (tok) { el.value = tok; return true; }
    } catch (e) {}
    return false;
  }

  function autoAssignMode() {
    window.__BD_SELECTED_MC = { value: "", name: "" };
    const sel = document.getElementById("id_medical_center");
    if (!sel) return true;
    let blank = Array.from(sel.options).find(o => o.value === "");
    if (!blank) {
      blank = document.createElement("option"); blank.value = ""; blank.textContent = "Auto assign";
      sel.insertBefore(blank, sel.firstChild);
    }
    sel.value = "";
    if (sel.value !== "") { blank.selected = true; }
    try {
      const $ = window.jQuery || window.$;
      if ($ && $.fn && $.fn.dropdown) { $(sel).dropdown("refresh"); $(sel).dropdown("set selected", ""); }
    } catch (e) {}
    if (sel.value !== "") { sel.selectedIndex = Array.from(sel.options).indexOf(blank); }
    return sel.value === "";
  }
  window.bdAutoAssignMode = autoAssignMode;

  function formReady() {
    const f = form(); if (!f) return { ok: false, bad: ["form"] };
    const bad = [];
    f.querySelectorAll("input,select,textarea").forEach(el => {
      if (el.name && el.name !== "captcha" && el.willValidate && !el.checkValidity()) bad.push(el.name);
    });
    const tc = f.querySelector('[name="traveled_country"]');
    if (cfg && tc && tc.value !== cfg.dest) bad.push("traveled_country(" + tc.value + "≠" + cfg.dest + ")");
    return { ok: bad.length === 0, bad };
  }

  async function prefill() {
    if (!cfg.profile || typeof window.bdAutoFill !== "function") return;
    info.phase = "filling"; push();
    window.__BD_SELECTED_MC = { value: "", name: "" };
    await window.bdAutoFill(Object.assign({}, cfg.profile, { traveled_country: cfg.dest }), { value: "" });
    autoAssignMode();
  }

  async function fire(c) {
    busy = true; stopTimer();
    info.fired = { id: c.id, name: c.name, dest: cfg.dest, at: Date.now() };
    if (cfg.sound !== false) beep();
    autoAssignMode();
    let r = formReady();
    if (!r.ok && cfg.profile) { await prefill(); r = formReady(); }
    if (!cfg.autoSubmit) {
      info.phase = "matched"; info.running = false; info.note = "Match found. Auto-submit is off: press the site's Submit button now.";
      cfg.armed = false; saveCfg(); busy = false; push(); return;
    }
    if (!r.ok) {
      info.phase = "blocked"; info.running = false; info.note = "Match found but form is incomplete: " + r.bad.join(", ");
      cfg.armed = false; saveCfg(); busy = false; push(); return;
    }
    info.phase = "submitting"; info.note = "Refreshing captcha…"; push();
    await freshCaptcha();
    autoAssignMode();
    try { sessionStorage.setItem(RKEY, JSON.stringify({ id: c.id, name: c.name, dest: cfg.dest, at: Date.now(), status: "submitted" })); } catch (e) {}
    try { sessionStorage.setItem("__bd_last_post", JSON.stringify({ medical_center: "", name: "", chosen: "", traveled_country: cfg.dest, forced: true, live: c, at: new Date().toISOString() })); } catch (e) {}
    cfg.armed = false; cfg.submittedAt = Date.now(); saveCfg();
    info.note = "Submitting with live center #" + c.id + " " + c.name; push();
    const f = form();
    autoAssignMode();
    const mcv = new FormData(f).get("medical_center");
    if (mcv) {
      info.phase = "blocked"; info.running = false;
      info.note = "Safety stop: form would send center #" + mcv + " instead of auto assign. Not submitted.";
      try { sessionStorage.removeItem(RKEY); } catch (e) {}
      busy = false; push(); return;
    }
    window.__bdBypassOnce = true;
    if (f.requestSubmit) f.requestSubmit(); else (window.__bdNativeSubmit || HTMLFormElement.prototype.submit).call(f);
    setTimeout(() => { window.__bdBypassOnce = false; }, 1500);
  }

  async function poll(checkOnly) {
    if (!checkOnly && (!info.running || busy)) return;
    try {
      const res = await fetch(location.pathname, { credentials: "same-origin", cache: "no-store", headers: { "accept": "text/html" } });
      if ([403, 429, 501, 503].includes(res.status)) {
        info.rl = (info.rl || 0) + 1;
        throw new Error("HTTP " + res.status + " (site is limiting checks, slowing down)");
      }
      const html = await res.text();
      const live = res.ok ? parseCMC(html) : null;
      if (!live || !Object.keys(live).length) throw new Error(res.ok ? "data not found (blocked / logged out?)" : "HTTP " + res.status);
      info.live = live; info.checkedAt = Date.now(); info.polls++; info.lastErr = ""; info.rl = 0;
      record(live);
      if (checkOnly) { push(); return; }
      const c = live[cfg.dest];
      if (c && cfg.targets.includes(c.id)) return fire(c);
      info.phase = "watching"; info.note = "";
      autoAssignMode();
    } catch (e) { info.errors++; info.lastErr = String(e.message || e); }
    push();
    if (!checkOnly) schedule();
  }
  function schedule() {
    stopTimer();
    if (!info.running) return;
    const base = Math.max(5, Number(cfg.interval) || 10) * 1000;
    let wait = base;
    if (info.rl) wait = Math.min(base * Math.pow(2, info.rl), 180000);
    else if (info.lastErr) wait = Math.min(base * 3, 60000);
    wait += Math.floor(Math.random() * 1500);
    info.nextAt = Date.now() + wait; push();
    timer = setTimeout(poll, wait);
  }
  function stopTimer() { if (timer) { clearTimeout(timer); timer = null; } }

  async function start(c) {
    cfg = Object.assign({ interval: 10, autoSubmit: true, sound: true }, c, { armed: true, submittedAt: 0 });
    cfg.targets = (cfg.targets || []).map(String);
    if (!cfg.targets.length || !cfg.dest) return { error: "Choose destination and at least one target center" };
    saveCfg();
    try { sessionStorage.removeItem(RKEY); } catch (e) {}
    cfg.interval = Math.min(120, Math.max(5, Number(cfg.interval) || 10));
    info.running = true; info.fired = null; info.errors = 0; info.lastErr = ""; info.rl = 0; info.note = ""; busy = true;
    await prefill();
    busy = false; info.phase = "watching"; push();
    poll();
    return true;
  }
  function stop() { info.running = false; info.phase = "idle"; info.note = "Stopped"; stopTimer(); if (cfg) { cfg.armed = false; saveCfg(); } push(); return true; }

  // initial reading from the page itself (zero extra requests)
  try {
    if (typeof COUNTRY_MEDICAL_CENTER !== "undefined") { info.live = toLive(COUNTRY_MEDICAL_CENTER); info.checkedAt = Date.now(); record(info.live); }
    else { const s = Array.from(document.scripts).map(x => x.textContent).join("\n"); const l = parseCMC(s); if (l) { info.live = l; info.checkedAt = Date.now(); record(l); } }
  } catch (e) {}

  try { cfg = JSON.parse(sessionStorage.getItem(CKEY) || "null"); } catch (e) {}
  if (isPay) {
    const r = getResult();
    if (r && r.status === "submitted") { r.status = "reached_pay"; r.payAt = Date.now(); try { sessionStorage.setItem(RKEY, JSON.stringify(r)); } catch (e) {} }
  } else if (isBooking && cfg && cfg.submittedAt && Date.now() - cfg.submittedAt < 120000) {
    const r = getResult();
    if (r && r.status === "submitted") { r.status = "returned"; try { sessionStorage.setItem(RKEY, JSON.stringify(r)); } catch (e) {} }
    info.note = "Last auto-submit came back to the form (site showed an error). Check the form, then Start again.";
    cfg.submittedAt = 0; saveCfg();
  }

  window.addEventListener("message", async e => {
    if (e.source !== window || !e.data || !e.data.__bd || e.data.type !== "req") return;
    const { id, cmd, args } = e.data;
    if (!/^mon/.test(cmd)) return;
    let result = null;
    try {
      if (cmd === "monStart") result = isBooking ? await start(args) : { error: "Open the Book Appointment page" };
      else if (cmd === "monStop") result = stop();
      else if (cmd === "monCheck") { await poll(true); result = info.live; }
      else if (cmd === "monClearLog") { localStorage.removeItem(LKEY); result = true; }
      else if (cmd === "monInfo") result = true;
    } catch (err) { result = { error: String(err) }; }
    post({ type: "res", id, result }); push();
  });
  setInterval(push, 1000);
  push();
})();
/* =================== END LIVE MONITOR =================== */
